import React from 'react';
import SpeechRecognition, { useSpeechRecognition } from 'react-speech-recognition';
import microPhoneIcon from "./microphone.svg";

const Dictaphone = () => {
  const {
    transcript,
    listening,
    resetTranscript,
    browserSupportsSpeechRecognition
  } = useSpeechRecognition();

  function returnTranscript() {return (<p>{transcript}</p>)};

  if (!browserSupportsSpeechRecognition) {
    return <span>Browser doesn't support speech recognition.</span>;
  }

  return (
    <div>
      <img src={microPhoneIcon} width="25" className="microphone-icon"  alt=" " />
      <p>Microphone Status: {listening ? 'On' : 'Off'}</p>
      <div class = "btn-group" role="group">
      <button type="button" class="btn btn-primary" onClick={SpeechRecognition.startListening}>Start</button>
      <button type="button" class="btn btn-primary" onClick={SpeechRecognition.stopListening}>Stop</button>
      <button type="button" class="btn btn-primary" onClick={resetTranscript}>Reset</button>
      <button type="button" class="btn btn-primary" onClick={returnTranscript}>Submit</button>
      </div>
      <p>Transcript: {transcript}</p>
    </div>
  );
};
export default Dictaphone;