import React from 'react';

import PivotTableUI from 'react-pivottable/PivotTableUI';
import 'react-pivottable/pivottable.css';
import TableRenderers from 'react-pivottable/TableRenderers';
import createPlotlyComponent from 'react-plotly.js/factory';
import createPlotlyRenderers from 'react-pivottable/PlotlyRenderers';
import { tips } from './tips.js';
import Dropzone from 'react-dropzone';
import Papa from 'papaparse';

// create Plotly React component via dependency injection
const Plot = createPlotlyComponent(window.Plotly);

// create Plotly renderers via dependency injection
const PlotlyRenderers = createPlotlyRenderers(Plot);

class PivotTableUISmartWrapper extends React.PureComponent {

    static getDerivedStateFromProps(newProps, state) {
       if(newProps.pivotState !== state.pivotState){

         const { pivotState } = newProps;
         return pivotState;
        }
        return null;
    }



    constructor(props, state, pivotState) {
        state = {};
        super(props);
        this.state = {pivotState: props};


    {
      this.setState(pivotState)
    }
    }

    render() {
        return (
            <PivotTableUI
                renderers={Object.assign(
                    {},
                    TableRenderers,
                    createPlotlyRenderers(Plot)
                )}
                {...this.state.pivotState}
                onChange={s => this.setState({pivotState: s})}
                unusedOrientationCutoff={Infinity}
            />
        );
    }
}

class PivotTable extends React.Component {

   state = {
            mode: 'demo',
            filename: 'Sample Dataset: Tips',
            pivotState: {
                data: tips,
            },
    }


    onDrop(files) {
        this.setState(
            {
                mode: 'thinking',
                filename: '(Parsing CSV...)',
                textarea: '',
                pivotState: {data: []},
            },
            () =>
                Papa.parse(files[0], {
                    skipEmptyLines: true,
                    error: e => alert(e),
                    complete: parsed =>
                        this.setState({
                            mode: 'file',
                            filename: files[0].name,
                            pivotState: {data: parsed.data},
                        }),
                })
        );
    }

    onType(event) {
        Papa.parse(event.target.value, {
            skipEmptyLines: true,
            error: e => alert(e),
            complete: parsed =>
                this.setState({
                    mode: 'text',
                    filename: 'Data from <textarea>',
                    textarea: event.target.value,
                    pivotState: {data: parsed.data},
                }),
        });
    }





    render() {
        return (

         <div className="container container-sm p-1">
      <h2 className="title text-center text-dark">Pivot Table Integration</h2>
      <p>This React component would allow users to visualize their data using the popular charting library, Plotly, and the React-Pivot Table library. The component would allow users to select from a variety of chart types, such as bar charts, line graphs, and scatter plots, and customize the data displayed in the chart. The React-Pivot Table library would allow users to easily filter and sort their data, as well as customize the table's appearance. The component would also allow users to export their data in a variety of formats, such as CSV, JSON, and Excel. Finally, the component would be fully responsive, allowing users to view their data on any device.</p>
        <div style={{ textAlign: "center" }}>
            <h3>CSV IMPORT EXAMPLE </h3>
            <div>
                <p>Try it on a file...</p>
                <div className="dropzone">
                    <Dropzone onDrop={this.onDrop.bind(this)}
                            accept={".csv"}
                            className="dropzone"
                            activeClassName="dropzoneActive"
                            rejectClassName="dropzoneReject">
                      {({getRootProps, getInputProps}) => (
                        <section>
                          <div {...getRootProps()}>
                            <input {...getInputProps()} />
                            <p>Drag 'n' drop some files here, or click to select files</p>
                          </div>
                          <br />
                        </section>
                      )}
                    </Dropzone>
                </div>
            </div>

        </div>
        <br />
        <h4 className="text-center">{this.state.filename}</h4>
            <div className = "PTable">

            <br />
                <PivotTableUISmartWrapper {...this.state.pivotState} />
            </div>
        </div>
        );
    }
}

export default PivotTable;

