import React, { useEffect, useState, useMemo } from "react"
import "./styles.scss"
import { Link } from "react-router-dom";
import { useAuth0 } from "@auth0/auth0-react";
import { Loading } from './'



let PageSize = 2;


const About = (user_check) => {


  const [currentPage, setCurrentPage] = useState(0);
  const [AboutData, setAboutData] = useState([])
  const [error, setError] = useState("")
  const url = 'https://portfolio-be-xmbi.onrender.com/about';
  const { user, loginWithRedirect, isLoading } = useAuth0();

   const fetchData = async () => {
    setError("")
    try {
      const response = await fetch(url)
      if (!response.ok) {
        // If the API responds meaningful error message,
        // then you can get it by calling response.statusText
        throw new Error("Sorry something went wrong")
      }
      const data = await response.json()
      console.log(data)
      setAboutData(Object.values(data))
      setCurrentPage(currentPage+1)
    } catch (error) {
      // It is always recommended to define the error messages
      // in the client side rather than simply relying on the server messages,
      // since server messages might not make sense to end user most of the time.
      setError(error.message)
    }
  }

    useEffect(() => {
    fetchData()
  }, [])

  const currentTableData = useMemo(() => {
  const firstPageIndex = (currentPage - 1) * PageSize;
  const lastPageIndex = firstPageIndex + PageSize;
  /*console.log(currentPage)*/
  return AboutData.slice(firstPageIndex, lastPageIndex);
  }, [currentPage]);

  if (isLoading) {
        return <Loading />;
      }

  return (
  <>
    <div className = "home hero-image bg-gradient-dark px-4 py-5 parallax">
          <div className="my-5">
          { isLoading ? <Loading />:
                <div className="hero-text">
                <h1>Meet the Team</h1><br/>
                { (user_check.nickname || user)? <p style = {{"fontSize":"20px", "maxWidth":"500px"}}>This page contains data that is pulled
                from a public backend API endpoint to display different profile cards that would represent different members of the team.
                </p>:<><p>Welcome, please select a Login below to see more.</p>
                <div className="d-grid gap-2 mt-3" style={{display:'block'}}>
                      <a style={{cursor: "pointer", margin:"10px"}} className='btn btn-outline-light' onClick={() => {(user_check.nickname || user)? window.location.href="/Portfolio/projects": loginWithRedirect()}} type="button" >
                        {(user_check.nickname || user)? "Projects" : "Auth0 Login" }
                      </a>
{/*                      {(user_check.nickname || user)? "": <> */}
{/*                       <a style={{cursor: "pointer", margin:"10px"}}className='btn btn-outline-light' onClick={() => {window.location.href="/Portfolio/login"}} type="button" > */}
{/*                         Alternative Login */}
{/*                       </a> </> } */}
                </div></>}

                </div>
                }
          </div>
    </div>

    <div className= "acontainer px-4 py-5">
      {error && <p>{error}</p>}
      {AboutData.length > 0 && (
        <div className="row center">
          {AboutData.map((item,index) => (
          <>
            <div className= "aboutcont col-md-6 col-centered" key={item.first}>
                <div className="card">
                    <div id="headingOne">
                          <img className = {`photo ${(user_check.nickname || user)? '' : 'blur'}`} src={require(`${item.img_url}`)} alt=" " />
                          <div className = "blogcontent">
                              <h5 className="mb-0">
                                <p>{item.First} {item.Last}</p>
                                <p>{item.Title} </p>
                              </h5>

                              <p className = {` ${(user_check.nickname || user)? '' : 'blur'}`}>{item.About_Me} </p>
                              <div className = "blogfooter">

                                    <Link className="btn btn-block btn-link text-right" type="button" to="/Portfolio/resume">
                                        Read more...
                                    </Link>
                                    {/*<p><button className="button" type = "button" data-target={`#${item.name}`}>Contact</button></p>*/}

                              </div>


                          </div>

                    </div>
                </div>

               <div id={item.first} className="collapse">
                      <div className="card">
                        <h6>Email: {item.email}</h6> <br/> <br/>

                      </div>
                  </div>

            </div>

          </>

          )) }

        </div>
      )}
    </div>
  </>
  )
}

export default About
