import { useAuth0 } from "@auth0/auth0-react";
import React, { useEffect, useState, useMemo } from "react"
import { getCookie, deleteCookie } from './AltLogin/Cookies.js'


function DeleteButton(props, user_check) {
  const { user, getAccessTokenSilently } = useAuth0();
  const [deletedUser, setDeletedUser] = useState(false)
  const [error, setError] = useState("")


  const domain = process.env.REACT_APP_AUTH0_DOMAIN;
  const clientId = process.env.REACT_APP_AUTH0_CLIENT_ID_P;
  const authpurl = process.env.REACT_APP_AUTH0_TOKEN_URL_P;
  const authcs = process.env.REACT_APP_AUTH0_CLIENT_S_P;
  const paudience = process.env.REACT_APP_AUDIENCE_P;
  const Grant_type = process.env.REACT_APP_GRANT_TYPE_P;
  const scope_t = process.env.REACT_APP_SCOPE;
  const DK = process.env.P_DK


  const user_c = getCookie('access_token')
  const CName = props.ClassName
  const SName = props.style

  const AltLogout = () => {
    deleteCookie('access_token')
    deleteCookie('user_access')
    deleteCookie('ajs_user_id')
    deleteCookie('user_email')
    window.location.reload();
  }

  const deletecurrentuser = async (e) => {
    console.log("delete user")
    try {
    const token2 = await getAccessTokenSilently({
            authorizationParams: {
              audience: `https://${domain}/api/v2/`,
            },
          });

    const userDByIdUrl = `https://portfolio_be-1-k2619905.deta.app/user/${user.sub}`;
    const response2 = await fetch(userDByIdUrl, {
          method: 'DELETE',
          headers: {
            Authorization: `Bearer ${token2}`,
            'content-type': 'application/json',
          },
    })
    if (!response2.ok) {
        console.log(response2.message)
        throw new Error("Sorry something went wrong " + response2.status_code)
    }
    const data = await response2.json()
    console.log(data)
    if (data === 204){
        setDeletedUser(true)
        window.location.reload();

    }
    } catch(error){
    setError("An Error has occurred: "+ error.message)
    console.log(error.message);
    }
  }

  const deleteAltUser = async (user_check) => {

    try {
        //const u_id = user_check.user_id
        //const u_id_encoded = window.btoa(u_id)
        const C_check = getCookie("access_token")
        const C_u_id = getCookie("ajs_user_id")
        let CE_u_id = C_u_id.replace("|","%7C")

        const url = `https://portfolio_be-1-k2619905.deta.app/private/user/delete/${CE_u_id}`
        if (C_check !== "" || C_check !== undefined){
            const response = await fetch(url, {
            method: 'DELETE',
            headers: {
             accept: "application/json",
              "API-COOKIE": C_check,
            },
        });

        if (!response.ok) {
            console.log(response.status)
            throw new Error("Sorry something went wrong when accessing private route. Response is : " + JSON.stringify(response))
        }
        const data = await response.json()
        console.log(data)
        if (data.status_code === 204){
            setDeletedUser(true)
            AltLogout()
            alert("Successfully removed user profile! Thank you for viewing this Portfolio.")
        }

        return
        /*console.log("response is " + ProjectData);
        console.log(data)
        console.log(Object.values(data))*/
    }
    } catch(error){ console.log(error)}

  }

if (user_c !== ""){return <a  className={CName} style={SName} onClick={() => deleteAltUser()}>
      Alternative Continue
    </a>}
else {
  return <a  className={CName} style={SName} onClick={() => deletecurrentuser()}>
      Auth0 Continue
    </a>
  }
};

export default DeleteButton;