import React, { useState, useRef,  useEffect } from "react";
import { NavLink } from "react-router-dom";
import  Profile from "./profile.js"
import  ProfileNav from "./ProfileNav"
import  DefaultProfile from "./DefaultProfile.js"
import LoginButton from './login.js'
import LogoutButton from './logout.js'
import { useAuth0 } from '@auth0/auth0-react';
import { getCookie } from './AltLogin/Cookies.js'


function Navigation(user_check) {

    const [colorChange, setColorchange] = useState(false);
    const changeNavbarColor = () => {
        if (window.scrollY >= 600) {
            setColorchange(true);
        }
        else {
            setColorchange(false);
        }
    };
    window.addEventListener('scroll', changeNavbarColor);

    const { user, isAuthenticated, isLoading } = useAuth0()
    const user_c = getCookie("access_token")

  const [navbarOpen, setNavbarOpen] = useState(false);
  const boxRef = useRef(null);
  const boxOutsideClick = OutsideClick(boxRef);


function OutsideClick(ref) {
    const [isClicked, setIsClicked] = useState();

  useEffect(() => {
    function handleClickOutside(event) {
        /*console.log("navbar " + navbarOpen)
        console.log(!ref.current.contains(event.target))*/
      if (navbarOpen===true && ref.current && !ref.current.contains(event.target)===true) {
        /*console.log("case check " + navbarOpen)*/
        setNavbarOpen(false)
        return navbarOpen;

      } else if (navbarOpen===true && ref.current && !ref.current.contains(event.target)===false){
        setNavbarOpen(true)
        return navbarOpen;

      } else {
         setNavbarOpen(false)
         return navbarOpen;
      }
    }

    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [ref, navbarOpen]);

  return isClicked;
}


  return (

    <div  ref={boxRef}>
      <nav className={`navbar fixed-top  ${colorChange ? ' bg-dark':' ' }`}>

          <NavLink className={` ${navbarOpen ? 'navbar-brand-open' : 'navbar-brand'}`} to="/">
            Portfolio
          </NavLink>
          <navbutton className = {` ${navbarOpen ? ' open' : 'toggle close'}`} onClick={() => setNavbarOpen(true)}>
                <div className="menu-line fadeInRight"></div>
                <div className="menu-line fadeInRight"></div>
                <div className="menu-line fadeInRight"></div>
          </navbutton>

            <ul className={`menu-nav mr-auto${navbarOpen ? ' show-menu' : ''}`}>
                <li className="nav-item dropdown fadeInLeft">
                    <a className="nav-link" id="navbarDropdownMenuLink" role="button" data-toggle="dropdown" aria-haspopup="true" aria-expanded="false">
                      {(isAuthenticated || user_c) ? <Profile {...user_check}/> : <DefaultProfile />}
                    </a>
                    <div className="dropdown-menu" aria-labelledby="navbarDropdownMenuLink">
                      {(isAuthenticated || user_c) && (
                       <a>
                        <NavLink className="nav-link dropdown-item" to="/Portfolio/admin" >
                          Admin Page
                        </NavLink>
                       </a>

                      )}
                      {(isAuthenticated || user_c)?<> <a>{isAuthenticated || user_c ?
                      <NavLink className="nav-link" to="/Portfolio/profile">Profile
                        </NavLink> : "Please Login"}</a><a><LogoutButton/></a> </>: <>
                      <a><LoginButton /></a>
{/*                       <a><a onClick={() => {window.location.href="/Portfolio/login"}} className="nav-link">Alternative Login</a> </a> */}
                      </>}
                    </div>
                </li>
              <li className="nav-item fadeInLeft">
                <NavLink className="nav-link" to="/Portfolio">
                  Home
                  <span className="sr-only">(current)</span>
                </NavLink>
              </li>
              <li className="nav-item fadeInLeft">
                <NavLink className="nav-link" to="/Portfolio/about">
                  About
                </NavLink>
              </li>
              {(isAuthenticated || user_c) && (
              <>
              <li className="nav-item fadeInLeft">
                <NavLink className="nav-link" to="/Portfolio/job-postings">
                  Jobs
                </NavLink>
              </li>
              <li className="nav-item fadeInLeft">
                <NavLink className="nav-link" to="/Portfolio/projects">
                  Projects
                </NavLink>
              </li>
              </>
              )}
            </ul>


      </nav>
    </div>
  );
}

export default Navigation;
