import { useAuth0 } from "@auth0/auth0-react";
import React, { useEffect, useState } from "react";

const Profile = (user_check) => {
      const { user, isAuthenticated, getAccessTokenSilently } = useAuth0();
      const [userMetadata, setUserMetadata] = useState(null);


    useEffect(() => {
      const getUserMetadata = async () => {
        const domain = "dev-test-services-env.us.auth0.com";

        try {
          const accessToken = await getAccessTokenSilently({
            authorizationParams: {
              audience: `https://${domain}/api/v2/`,
              scope: "read:current_user",
            },
          });

          const userDetailsByIdUrl = `https://${domain}/api/v2/users/${user.sub}`;

          const metadataResponse = await fetch(userDetailsByIdUrl, {
            headers: {
              Authorization: `Bearer ${accessToken}`,
            },
          });

          const { user_metadata } = await metadataResponse.json();

          setUserMetadata(user_metadata);
        } catch (e) {
          console.log(e.message);
        }
      };

      getUserMetadata();
    }, [getAccessTokenSilently, user?.sub]);




  return (
    (isAuthenticated || user_check) && (
      <div>
        <img src={user? user.picture: user_check.picture} alt={user? user.name: user_check.name}
        style={{width: 30, height: 30, borderRadius: 30/ 2}} />
        {/* <h3>User Memo</h3>
        {userMetadata ? (
          <pre class = "text-light" >{JSON.stringify(userMetadata, null, 2)}</pre>
        ) : (
          "No user metadata defined - update on Auth0"
        )}*/}
      </div>
    )
  );
};

export default Profile;