import React, { useEffect, useState } from "react";
import "./index.css";
import { BrowserRouter as Router, Route, Routes, Navigate } from "react-router-dom";
import { useAuth0 } from "@auth0/auth0-react";
import ProtectedRoute from './auth/ProtectedRoute';
import ReactGA from "react-ga4";
import CookieConsent, {
  getCookieConsentValue,
  Cookies,
} from "react-cookie-consent";
import { getCookie } from './components/AltLogin/Cookies.js'
import  AltAuth from './auth/AltAuth.tsx'


import {
  Navigation,
  Footer,
  Home,
  About,
  JPostings,
  Project,
  ScrollToTop,
  Loading,
  LoginPage,
  Resume,
  AdminPage,
  MainProfile,
  MultiLogin,
} from "./components";

import BlogDetails from './components/BlogDetails';
/*import {ET_Home} from './components/ET';
import GraphQL_App from './components/graphQL/GraphQL_App';*/



export default function App(){

    const [user_check, setUser_Check] = useState()
    const [pc, setPC] = useState(0)
    const [isLoadingg, setIsLoadingg] = useState(false)
    const { user, isAuthenticated, isLoading, error, error_description } = useAuth0();
    const user_c = getCookie('access_token')


    // const [os, setOs] = useState('');
    useEffect(() => {
        setIsLoadingg(true)
        const user_c = getCookie('access_token')
        async function initial() {
            const user = await AltAuth()
            // console.log(user.user_A + ") initial_check( " + user.user_c + " )last")
            if (user) {
            setUser_Check(JSON.parse(user.user_A))
             setPC(1)}
            else { setUser_Check('No User')}
        }

        if (!user && !user_c) {setUser_Check()}
        else if (user){
        console.log("check this")
        setUser_Check(user)
        } else if (user_c){ if (user_check !== 'No User' && pc !== 1) {initial()}
        } else { setUser_Check('No User')}
//        console.log(user_check)
        setIsLoadingg(false)
      }, [user_check]);


    const handleAcceptCookie = () => {
    const isConsent = getCookieConsentValue();
    if (process.env.REACT_APP_GOOGLE_ANALYTICS_ID && isConsent==="true") {
     ReactGA.initialize(process.env.REACT_APP_GOOGLE_ANALYTICS_ID);
    }
  };

    useEffect(() => {
    const isConsent = getCookieConsentValue();
    if (isConsent === "true") {
      handleAcceptCookie();
    }
  }, []);


      if (error) {
        console.log(error + " " + error_description)

      }
      if (isLoading && pc !== 1 || isLoadingg) {
        return <Loading />;
      }


  const handleDeclineCookie = () => {
    //remove google analytics cookies
    const GA_sesh = process.env.REACT_APP_GOOGLE_ANALYTICS_ID
    const n_sesh = GA_sesh.substring(2)
    Cookies.remove("_ga");
    Cookies.remove("_ga_"+ n_sesh);
    Cookies.remove("_gat");
    Cookies.remove("_gid");
    alert("You have selected to decline cookies! Some features may not work properly.")
  };


  return(
  <>
        <CookieConsent
        disableButtonStyles ={true}
        enableDeclineButton
        buttonText="I Understand"
        declineButtonText = "I Decline"
        onAccept={handleAcceptCookie}
        onDecline={handleDeclineCookie}
        buttonClasses="btn btn-primary"
        buttonStyle={{"margin": "10px"}}
        declineButtonClasses="btn btn-danger"
        expires={7}
        style={{ background: "black" }}
        overlay

      >
        This website uses cookies and Google Analytics to enhance the user experience.
      </CookieConsent>

     <ScrollToTop>
        <Navigation {...user_check}/>
            <Routes basename="/Portfolio">
              <Route path="/Portfolio" element={<Home {...user_check}/>} />
              <Route path="/Portfolio/signup" element={<MultiLogin />} />
              <Route path="/Portfolio/login" element={<LoginPage />} />
              <Route path="Portfolio/about" element={<About {...user_check}/>} />

              <Route path="/Portfolio/resume" element={ <ProtectedRoute> <Resume /></ProtectedRoute>} />
              {(isAuthenticated || user_c !== undefined) && (
              <>
              <Route path="Portfolio/profile" element={<ProtectedRoute><MainProfile {...user_check}/></ProtectedRoute>} />
              <Route path="/Portfolio/job-postings" element={ <ProtectedRoute >
                    <JPostings {...user_check}/>
                     </ProtectedRoute>} />
              <Route path="/Portfolio/projects" element={ <ProtectedRoute>
                    <Project {...user_check}/>
                     </ProtectedRoute>} />
              <Route path="/Portfolio/projects/:slug" element={<BlogDetails {...user_check}/>} />

              <Route path="/Portfolio/admin" element={ <ProtectedRoute> <AdminPage {...user_check}/> </ProtectedRoute>} />
              </>
              )}
              <Route
                    path="*"
                    element={<Navigate to="/Portfolio" replace />}
               />
            </Routes>
            <Footer />
     </ScrollToTop>
  </>
);
}

