import React, { useState, useRef, useEffect } from 'react';
import { saveAs } from 'file-saver';
import { mean, median, std } from 'mathjs';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
  PointElement,
  LineElement,
  LineController,
} from 'chart.js';

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
  PointElement,
  LineElement,
  LineController,

);


const MonteCarloSimulation = () => {
  const [initialInvestment, setInitialInvestment] = useState('');
  const [growthRate, setGrowthRate] = useState('');
  const [numYears, setNumYears] = useState('');
  const [numSimulations, setNumSimulations] = useState('');
  const [simulationResults, setSimulationResults] = useState([]);
  const [chartData, setChartData] = useState(null);
  const chartRef = useRef(null);

  useEffect(() => {
    // Generate the chart data when simulation results change
    if (simulationResults.length > 0) {
      const labels = Array.from({ length: numYears + 1 }, (_, i) => `Year ${i}`);
      const datasets = simulationResults.map((simulation, index) => ({
        label: `Simulation ${index + 1}`,
        data: simulation,
        borderColor: getRandomColor(),
        fill: false,
        borderWidth: 1,
      }));
      setChartData({ labels, datasets });
    }
  }, [simulationResults, numYears]);

  const runSimulation = () => {
    const simulations = [];
    for (let i = 0; i < numSimulations; i++) {
      let investment = initialInvestment;
      const values = [investment];
      for (let j = 0; j < numYears; j++) {
        investment *= 1 + Math.random() * 2 * growthRate/100 - growthRate/100;
        values.push(investment.toFixed(2));
      }
      simulations.push(values);
    }
    setSimulationResults(simulations);
  };

  const downloadSimulationData = () => {
    const csvContent = simulationResults.map(simulation => simulation.join(',')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8' });
    saveAs(blob, 'simulation_data.csv');
  };

  const downloadPlot = () => {
    setTimeout(() => {
      console.log(chartRef)
      const canvas = chartRef.current.canvas; // Get the chart canvas element
      const dataURL = canvas.toDataURL('image/png');
      saveAs(dataURL, 'simulation_plot.png');
    }, 100); // Delay the download by 100 milliseconds to allow the chart to render
  };

  const getRandomColor = () => {
    const letters = '0123456789ABCDEF';
    let color = '#';
    for (let i = 0; i < 6; i++) {
      color += letters[Math.floor(Math.random() * 16)];
    }
    return color;
  };

  const displaySimulationResults = () => {
    return simulationResults.map((simulation, index) => (
      <div key={index}>
        <h4>Simulation {index + 1}:</h4>
        {simulation.map((value, year) => (
          <p key={year}>Year {year}: ${value}</p>
        ))}
        <hr />
      </div>
    ));
  };

  const displayMeasuresOfCentralTendency = () => {
    const allValues = simulationResults.flat();
    const centralTendencyMean = mean(allValues);
    const centralTendencyMedian = median(allValues);
    const centralTendencyStdDev = std(allValues);

    return (
      <div>
        <h3>Measures of Central Tendency:</h3>
        <p>Mean: ${centralTendencyMean.toFixed(2)}</p>
        <p>Median: ${centralTendencyMedian.toFixed(2)}</p>
        <p>Standard Deviation: ${centralTendencyStdDev.toFixed(2)}</p>
      </div>
    );
  };



  const displayWaterFallChart = () => {
    const allValues = simulationResults.flat();
    const centralTendencyMean = mean(allValues);
    const centralTendencyMedian = median(allValues);
    const centralTendencyStdDev = std(allValues);

    return (
      <div>
        <h3>Water Fall Chart:</h3>
        <p>Mean: ${centralTendencyMean.toFixed(2)}</p>
        <p>Median: ${centralTendencyMedian.toFixed(2)}</p>
        <p>Standard Deviation: ${centralTendencyStdDev.toFixed(2)}</p>
      </div>
    );
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    scales: {
      x: {
        title: {display: true, text: 'Year(s)'},
        type: 'category', // Use category scale for x-axis
        beginAtZero: true,
      },
      y: {
        title: {display: true, text: '$ Amount'},
        type: 'linear',
        beginAtZero: false,
      },
    },
  };

  const legend = {
  display: true,
  position: "bottom",
  labels: {
    fontColor: "#323130",
    fontSize: 14
      }
    };

  return (
    <div className="container container-sm p-1">
    <div className="row ">
    <div className= "col-lg-5">
      <h2 className= "text-center">Monte Carlo Simulation</h2>
      <p> A Monte Carlo Simulation is a computational technique that uses random sampling and statistical analysis to model and solve complex problems or analyze systems that involve uncertainty. In a Monte Carlo simulation, the problem or system under study is represented using mathematical models or algorithms. Random sampling is then used to generate a large number of possible outcomes or scenarios, based on the input variables and their respective probability distributions. These outcomes are typically generated using random number generators.
By simulating a large number of scenarios, the Monte Carlo method provides a statistical estimate of the possible outcomes and their associated probabilities. This allows analysts to gain insights into the behavior of the system, understand the range of possible outcomes, assess risks, and make informed decisions based on the simulation results.
</p>
    </div>
    <div style={{maxWidth: "300px", margin:"auto"}} className="col-lg-5">
      <div className="form-group">
        <label>Initial Investment:</label>
        <input
          required
          type="number"
          className="shadow-lg form-control"
          value={initialInvestment}
          onChange={(e) => setInitialInvestment(parseFloat(e.target.value))}
        />
      </div>
      <div className="form-group">
        <label>Growth Rate (%):</label>
        <input
          required
          type="number"
          className="shadow-lg form-control"
          value={growthRate}
          onChange={(e) => setGrowthRate(parseFloat(e.target.value))}
        />
      </div>
      <div className="form-group">
        <label>Number of Years:</label>
        <input
          required
          type="number"
          className="shadow-lg form-control"
          value={numYears}
          onChange={(e) => setNumYears(parseInt(e.target.value))}
        />
      </div>
      <div className="form-group">
        <label>Number of Simulations:</label>
        <select
          required
          type="number"
          className="shadow-lg form-control"
          value={numSimulations}
          onChange={(e) => setNumSimulations(parseInt(e.target.value))}
        >
        <option value="">-</option>
        <option value="5">5</option>
        <option value="10">10</option>
        <option value="30">30</option>
        <option value="50">50</option>
        </select>
      </div>

      <div>
        <button type="button" className="btn btn-primary"  onClick={runSimulation}>Run Simulation</button>
      </div>
      </div>
      </div>
      <br/>
      {simulationResults.length > 0 && (
        <div>
          <h2>Simulation Results:</h2>
          <br/>
          {chartData && (
            <div>
              <h2>Simulation Plot:</h2>
              <Line
                style={{maxHeight:"500px", minHeight:"300px"}}
                ref={chartRef}
                legend={legend}
                data={{
                  labels: chartData.labels,
                  datasets: chartData.datasets,
                }}
                options={options}
              />
            </div>

          )}
          <br />
          <div>
            <button onClick={downloadSimulationData}>Download CSV</button>
            <button onClick={downloadPlot}>Download Plot</button>
          </div>
          {displayMeasuresOfCentralTendency()}
        </div>
      )}
    </div>
  );
};

export default MonteCarloSimulation;
