import { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import ReactMarkdown from 'react-markdown'
import { getCookie } from '../components/AltLogin/Cookies.js'


import { useAuth0 } from "@auth0/auth0-react";



const BlogDetails = (user_check) => {
 const navigate = useNavigate();
 const { slug } = useParams();
// const url = `http://127.0.0.1:8000/blog/posts/${slug}`
// const url = `http://127.0.0.1:8000/blog_/${slug}`
 const url = `https://portfolio-be-xmbi.onrender.com/blog_/${slug}`
 const [error, setError] = useState()
 const [mderror, setMdError] = useState()
 const [ProjectData, setProjectData] = useState([])
 const [tosText, setTosText] = useState('')
 const { getAccessTokenSilently } = useAuth0();

  const file_name = `${slug}`;
  const domain = process.env.REACT_APP_AUTH0_DOMAIN;
  const clientId = process.env.REACT_APP_AUTH0_CLIENT_ID;
  const authpurl = process.env.P_REACT_APP_AUTH0_TOKEN_URL
  const authcs = process.env.P_REACT_APP_AUTH0_CLIENT_S
  const paudience = process.env.P_REACT_APP_AUDIENCE
  const Grant_type = process.env.P_REACT_APP_GRANT_TYPE


  const fetchProtectedData = async () => {

    const C_check = getCookie("access_token")

    try {
        if (C_check !== "" || C_check !== undefined){
            const response = await fetch(url, {
            headers: {
             accept: "application/json",
              "API-COOKIE": C_check,
            },
        });

        if (!response.ok) {
            console.log(response.status)
            throw new Error("Sorry something went wrong when accessing private route. Response is : " + JSON.stringify(response))
        }
        const data = await response.json()
        setProjectData(data)
        return
    }} catch(error){
; console.log(error)}

    try {
    const token = await getAccessTokenSilently(authpurl, {
        method: "POST",
        header: {
         "content-type": "application/x-www-form-urlencoded"},
        "client_id":clientId,
        "client_secret":authcs,
        "audience":paudience,
        "grant_type":Grant_type
                });
    

    const response = await fetch(url, {
        headers: {
         accept: "application/json",
         authorization: `Bearer ${token}`,
        },
    });

    if (!response.ok) {
        console.log(response.status)
        throw new Error("Sorry something went wrong when accessing private route")
    }

    const data = await response.json()
    setProjectData(data)

    } catch(error){

    setError("Error "+ error.message)
    console.log(error.message);
    }
  }


    useEffect((user_check) => {
    fetchProtectedData()
    /*console.log(ProjectData)*/
  }, [user_check])

//  useEffect(() => {
//    import(`./project/Markdown_files/${file_name}.md`)
//    .then(res => {fetch(res.default)
//                    .then(res => res.text())
//                    .then(res => setTosText(res))
//                    .catch(err => console.log(err));
//            })
//            .catch(err => setMdError(err));
//    });



 return (
 <>
 { error? (<>
 <div className= "home hero-image bg-gradient-dark px-4 py-5 parallax">
    <div className = "hero-text">
        <h1>{error}</h1>
    </div>
 </div>
 </>

 ) : (


 <>



 <>

     <div className = "home hero-image bg-gradient-dark px-4 py-5 parallax" key = {ProjectData.title}>
          <div className="my-5">
                <div className="hero-text">
                <h1>{ProjectData.title}</h1>
                <br />
                <button className="btn btn-primary" onClick={() => navigate(-1)}>
                  Go Back
               </button>
                </div>

          </div>
    </div>

    <div className="container">

       <div>
          <div className="flex-container">

          <br />
          <img src={ProjectData.imageurl} alt="" className="blogdimage" style= {{"maxHeight": "450px"}} />

             <div >
                <div className= "my-5">
                <ReactMarkdown children={ProjectData.maincontent} />
                </div>
             </div>
          </div>
       </div>
    </div>
 </>
   </>)
 } </>);
};


export default BlogDetails;