import { useLocation, Navigate, Outlet} from "react-router-dom";
import { useAuth0 } from '@auth0/auth0-react';
import React, { useEffect, useState } from "react";
import { Loading } from "../components";
import { getCookie, setCookie } from '../components/AltLogin/Cookies.js'
import  AltAuth from './AltAuth.tsx'


export default function ProtectedRoute({ children }: { children: JSX.Element }) {

  const user_c = getCookie('access_token');
  const { user, loginWithRedirect, isLoading, isAuthenticated } = useAuth0();



  const location = useLocation();
  let R = window.location.pathname
  const eV = [''];


  function new_eV(user, user_c) {
      //console.log("user_c2 is " + user_c.email_verified)
      if ( user_c !== "" || user.email_verified === true) {
     let eV = ['/projects','/Portfolio/projects', '/Portfolio/resume','/resume', '/Portfolio/job-postings','/job-postings','/Portfolio/admin','/admin', '/Portfolio/profile','/profile'];
     return eV;
  } else if (user_c !== "" || user) {
       let eV = [ '/Portfolio/profile','/profile'];
     return eV;
  }
  else {return ['Not Email Verified']}
}

  if (isLoading) {
        return <Loading />;
      }

// Need to review this section due to auth0 user but not allowing it through

  if (user || user_c) {
    let neV = new_eV(user, user_c)
    const isFound = neV.includes(R)
    if (isFound == true){
        return  children ? children : <Outlet />;
        } else {
        alert("Please Verify Email to continue to page. Redirecting to home page.")
        return <Navigate to= "/" />;
        }
  }

  if (!user_c && !user) { return <Navigate to= "/"/> }
  else if (!user_c ){
       return <Navigate to= "/Portfolio/login"/>;
  }
  else if (!user) {
        return <Navigate to= {loginWithRedirect({    appState: {
           previousPath: window.location.pathname // here
        }})} state={{ location }} />;
  }



}

