import React, { useEffect, useState, useMemo } from "react"
import { useAuth0 } from "@auth0/auth0-react";
import { useNavigate, Link } from 'react-router-dom';
import { getCookie, setCookie } from '../AltLogin/Cookies.js'

//MRT Imports
//import MaterialReactTable, { type MRT_ColumnDef } from 'material-react-table'; //default import deprecated
import { MaterialReactTable, type MRT_ColumnDef } from 'material-react-table';

//Material UI Imports
import { Box, Button, ListItemIcon, MenuItem, Typography } from '@mui/material';


//Icons Imports
import { AccountCircle, Send } from '@mui/icons-material';

//Mock Data
import  { data }  from './makeData.js';

export type Employee = {
  firstName: string;
  lastName: string;
  email: string;
  jobTitle: string;
  salary: number;
  startDate: string;
  signatureCatchPhrase: string;
  avatar: string;
};

const Example = () => {

  const [uData, setUData] = useState([])
  const [error, setError] = useState("")
  const url = 'https://portfolio_be-1-k2619905.deta.app/users';
   const { user, isAuthenticated, getAccessTokenSilently } = useAuth0();

  const domain = process.env.REACT_APP_AUTH0_DOMAIN;
  const clientId = process.env.REACT_APP_AUTH0_CLIENT_ID;
  const authpurl = process.env.P_REACT_APP_AUTH0_TOKEN_URL
  const authcs = process.env.P_REACT_APP_AUTH0_CLIENT_S
  const paudience = process.env.P_REACT_APP_AUDIENCE
  const Grant_type = process.env.P_REACT_APP_GRANT_TYPE

  const fetchProtectedData = async () => {

    const C_check = getCookie("access_token")
    try {
        if (C_check !== "" || C_check !== undefined){
            const response = await fetch(url, {
            headers: {

             accept: "application/json",
              "API-COOKIE": C_check,
            },
        });

        if (!response.ok) {
            console.log(response.status)
            throw new Error("Sorry something went wrong when accessing private route. Response is : " + JSON.stringify(response))
        }
        const data = await response.json()
        setUData(data)


        return
    }
    } catch(error){ console.log(error)}


    try {
    const token = await getAccessTokenSilently(authpurl, {
        method: "POST",
        header: {
         "content-type": "application/x-www-form-urlencoded"},
        "client_id":clientId,
        "client_secret":authcs,
        "audience":paudience,
        "grant_type":Grant_type
                });

    const response = await fetch(url, {
        headers: {
         accept: "application/json",
         authorization: `Bearer ${token}`,
        },
    });

    if (!response.ok) {
        console.log(response.status)
        throw new Error("Sorry something went wrong when accessing private route. Response is :" + response.status)
    }

    const data = await response.json()
    setUData(data)
    console.log(data)
    } catch(error){

    setError("An Error has occurred: "+ error.message)
    console.log(error.message);
    }
  }


  useEffect(() => {
    fetchProtectedData()
    console.log(uData)
  }, [])


  const columns = useMemo<MRT_ColumnDef>(
    () => [
      {
        id: 'user', //id used to define `group` column
        header: 'User Info',
        columns: [
          {
            accessorFn: (row) => `${row.firstname} ${row.lastname}`, //accessorFn used to join multiple data into a single cell
            id: 'Name', //id is still required when using accessorFn instead of accessorKey
            header: 'Name',
            size: 200,
            Cell: ({ renderedCellValue, row }) => (
              <Box
                sx={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '1rem',
                }}
              >
                <img
                  alt="avatar"
                  height={30}
                  src={row.original.img_url}
                  loading="lazy"
                  style={{ borderRadius: '50%' }}

                />
                {/* using renderedCellValue instead of cell.getValue() preserves filter match highlighting */}
                <span>{renderedCellValue}</span>
              </Box>
            ),
          },
          {
            accessorKey: 'username', //hey a simple column for once
            header: 'UserName',
            size: 60,
          },
        ],
      },
      {
        id: 'id',
        header: 'Role Info',
        columns: [

          {
            accessorKey: 'role', //hey a simple column for once
            header: 'Role',
            size: 100,
          },
          {
            accessorFn: (row) => new Date(row.startDate), //convert to Date for sorting and filtering
            id: 'startDate',
            header: 'Start Date',
            filterFn: 'lessThanOrEqualTo',
            sortingFn: 'datetime',
            Cell: ({ cell }) => cell.getValue<Date>()?.toLocaleDateString(), //render Date as a string
            Header: ({ column }) => <em>{column.columnDef.header}</em>, //custom header markup
            //Custom Date Picker Filter from @mui/x-date-pickers

          },
        ],
      },
    ],
    [],
  );

  return (
    <MaterialReactTable
      style={{ "overflowX": 'scroll'}}
      columns={columns}
      data={uData}
      enableColumnFilterModes
      enableColumnOrdering
      enableGrouping
      enablePinning
      enableRowActions
      enableRowSelection
      initialState={{ showColumnFilters: false }}
      positionToolbarAlertBanner="bottom"
      renderDetailPanel={({ row }) => (
        <Box
          sx={{
            display: 'flex',
            justifyContent: 'space-around',
            alignItems: 'center',
          }}
        >
          <img
            alt="avatar"
            height={100}
            src={row.original.img_url}
            loading="lazy"
            style={{ borderRadius: '50%' }}
          />
          <Box sx={{ textAlign: 'center' }}>
            <Typography variant="p">Signature Catch Phrase:</Typography>
            <Typography variant="p">
              &quot;{row.original.signatureCatchPhrase}&quot;
            </Typography>
          </Box>
        </Box>
      )}
      renderRowActionMenuItems={({ closeMenu }) => [
        <MenuItem
          key={0}
          onClick={() => {
            // View profile logic...
            closeMenu();
          }}
          sx={{ m: 0 }}
        >
          <ListItemIcon>
            <AccountCircle />
          </ListItemIcon>
          View Profile
        </MenuItem>,
        <MenuItem
          key={1}
          onClick={() => {
            // Send email logic...
            closeMenu();
          }}
          sx={{ m: 0 }}
        >
          <ListItemIcon>
            <Send />
          </ListItemIcon>
          Send Email
        </MenuItem>,
      ]}
      renderTopToolbarCustomActions={({ table }) => {
        const handleDeactivate = () => {
          table.getSelectedRowModel().flatRows.map((row) => {
            alert('Assign Role ' + row.getValue('firstname'));
          });
        };

        const handleActivate = () => {
          table.getSelectedRowModel().flatRows.map((row) => {
            alert('activating ' + row.getValue('firstname'));
          });
        };

        const handleContact = () => {
          table.getSelectedRowModel().flatRows.map((row) => {
            alert('contact ' + row.getValue('firstname'));
          });
        };

        return (
          <div style={{ display: 'flex', gap: '0.5rem'}}>
            <Button
              color="error"
              disabled={!table.getIsSomeRowsSelected()}
              onClick={handleDeactivate}
              variant="contained"
            >
              Assign Role
            </Button>
            <Button
              color="success"
              disabled={!table.getIsSomeRowsSelected()}
              onClick={handleActivate}
              variant="contained"
            >
              Activate
            </Button>
            <Button
              color="info"
              disabled={!table.getIsSomeRowsSelected()}
              onClick={handleContact}
              variant="contained"
            >
              Contact
            </Button>
          </div>
        );
      }}
    />
  );
};

export default Example;
