import React, { useEffect, useState, useMemo } from "react"
import Pagination from './Pagination'
import JPost from './JPost'
import { useAuth0 } from "@auth0/auth0-react";
import { getCookie } from './AltLogin/Cookies.js'


let PageSize = 5;


const SkillsSection = (user_check) => {
  const [currentPage, setCurrentPage] = useState(0);
  const [SkillData, setSkillData] = useState([])
  const [error, setError] = useState("")
  const [Active, setActive] = useState(false)
  const [isLoading, setIsLoading] = useState()
  const [searchFilter, setSearchFilter] = useState('Harness Engineer')
  const [Summary, setSummary] = useState("")
  const [Response, setResponse] = useState("")
  const [SummaryText, setSummaryText] = useState("Hello and welcome to the skills in demand section. Please search or select a specific skill to see more.")
  const url = 'https://portfolio_be-1-k2619905.deta.app/jobs/skills';
  const { user, isAuthenticated, getAccessTokenSilently } = useAuth0();

  const domain = process.env.REACT_APP_AUTH0_DOMAIN;
  const clientId = process.env.REACT_APP_AUTH0_CLIENT_ID;
  const authpurl = process.env.P_REACT_APP_AUTH0_TOKEN_URL
  const authcs = process.env.P_REACT_APP_AUTH0_CLIENT_S
  const paudience = process.env.P_REACT_APP_AUDIENCE
  const Grant_type = process.env.P_REACT_APP_GRANT_TYPE
  const DK = process.env.P_DK

  const [topic, setTopic] = useState({topic: ""})
  const [filteredData, setFilteredData] = useState(SkillData)
  const [cat, setCat] = useState('All Topics')

    const handleChange = async (e) => {
    e.preventDefault();
     try {
        await fetchTopicData()

    } catch (e) {
        alert(`Sending Request Failed`)
    }
    };

    const fetchTopicData = async () => {

        const C_check = getCookie("access_token")
        const url1 = "https://portfolio_be-1-k2619905.deta.app/public/summarize-topic?topic_i="
        try {
            if (C_check !== "" || C_check !== undefined){
                const response = await fetch(url1, {
                headers: {
                 accept: "application/json",
                  "API-COOKIE": C_check,
                },
            });

            if (!response.ok) {
                console.log(response.status)
                throw new Error("Sorry something went wrong when accessing private route. Response is : " + JSON.stringify(response))
            }
            const data = await response.json()
            setResponse(Object.values(data))

            return

        }} catch(error){ console.log(error)}

    try {
    const token = await getAccessTokenSilently(authpurl, {
        method: "POST",
        header: {
         "content-type": "application/x-www-form-urlencoded"},
        "client_id":clientId,
        "client_secret":authcs,
        "audience":paudience,
        "grant_type":Grant_type,

                });

    const m = document.getElementById("topic")
    console.log(m.value)
    const url1 = "https://portfolio_be-1-k2619905.deta.app/public/summarize-topic?topic_i="
    const response = await fetch(url1 + m.value, {
        method: 'GET',
        headers: {
         accept: "application/json",
         authorization: `Bearer ${token}`,

        },
    });
    if (!response.ok) {
        console.log(response.status)
        throw new Error("Sorry something went wrong when accessing private route. Response is :" + response.status)
    }
    const data = await response.json()
    setResponse(Object.values(data))
    } catch(error){
    setError("An Error has occurred: "+ error.message)
    console.log(error.message);
    }
  }


  function myFunction() {

    if (Active === true) {
  // Declare variables
  var input, filter, ul, li, a, i;
  input = document.getElementById("mySearch");
  filter = input.value.toUpperCase();
  ul = document.getElementById("myMenu");
  li = ul.getElementsByTagName("li");

  // Loop through all list items, and hide those who don't match the search query
  for (i = 0; i < li.length; i++) {
    a = li[i].getElementsByTagName("a")[0];
    if (a.innerHTML.toUpperCase().indexOf(filter) > -1) {
      li[i].style.display = "block";
    } else {
      li[i].style.display = "none";
    }
  }
  }
}

  const Filter_Topic = async (th) => {
    setSummaryText("Loading...")
    setFilteredData(
      SkillData.filter(s => {
        return (
          (th === s.topic_search)
        )
      })

    )
    setSummaryText("Hello and welcome to the skills in demand section. Please search or select a specific skill to see more.")
    //return(filteredData)
  }

  const openSearch = async (e) => {
    e.preventDefault()
     // console.log("cat1 is "+cat)
      //setCat(e.target.innerText)
      //setSummaryText('Loading...')
     // console.log("cat2 is "+cat)
      setCat(e.target.innerText)
      Filter_Topic(e.target.innerText)
      //console.log("cat3 is "+cat)
  }

  const myClick = (e) => {
        setSummary(e.target.innerText)
    }

  const displaysummary = () => {
    var input, i, c, d

    for (i = 0; i < SkillData.length; i++) {
        c = SkillData[i].topic;

        if (c === Summary) {
            /*console.log(c)*/
            input = SkillData[i].summary
            d = SkillData[i].topic_search
            return <><div>Topic: {d}</div><br/><div>{input}</div></>

        } else {
            input = "Hello and welcome to the skills in demand section. \n Please search or select a specific skill to see more."
        }
        /*console.log(input)*/
    }
    return (
      <div>
            {SummaryText}
      </div>
    );

  };

  const fetchProtectedData = async () => {

    const C_check = getCookie("access_token")
    try {
        if (C_check !== "" || C_check !== undefined){
            const response = await fetch(url, {
            headers: {
             accept: "application/json",
              "API-COOKIE": C_check,
            },
        });

        if (!response.ok) {
            console.log(response.status)
            throw new Error("Sorry something went wrong when accessing private route. Response is : " + JSON.stringify(response))
        }
        const data = await response.json()

        setSkillData(Object.values(data))
        setFilteredData(Object.values(data))
        setActive(true)
        return

    }} catch(error){ console.log(error)}


    try {
    const token = await getAccessTokenSilently(authpurl, {
        method: "POST",
        header: {
         "content-type": "application/x-www-form-urlencoded"},
        "client_id":clientId,
        "client_secret":authcs,
        "audience":paudience,
        "grant_type":Grant_type,

                });


    const response = await fetch(url, {
        headers: {
         accept: "application/json",
         authorization: `Bearer ${token}`,
        },
    });

    if (!response.ok) {
        console.log(response.status)
        throw new Error("Sorry something went wrong when accessing private route. Response is :" + response.status)
    }


    const data = await response.json()

    setSkillData(Object.values(data))
    setFilteredData(Object.values(data))
    setActive(true)
    } catch(error){

    setError("An Error has occurred: "+ error.message)
    console.log(error.message);
    }
  }
  const [filteredTopic, setFilteredTopic] = useState(SkillData)
  useEffect( () => {

    fetchProtectedData()
    Filter_Topic()
  }, [])

    const showskilllist = () => {

    return (

            <div className="Slist">
                <ul id="myMenu" >
                   {filteredData.map((item,index) => (
                      <li id={item.topic} onClick={myClick}><a>{item.topic}</a></li>
                    ))}
                </ul>
            </div>

    );
  }

  const showtopicresponse = () => {
    if (Response) {
    return (
    <div className="tresponse right center">
      <div className="tresponsetext">
        <h2>Summary</h2>
         <p>{Response}</p>
      </div>
    </div>
    );
    }
  }

    const S_Topics = Array.from(
    new Set(SkillData.map(skill => skill.topic_search))
  )

  return (
  <>

    <div id="SID" className=" px-4 py-5" style={{maxWidth:'1200px', margin: 'auto'}}>
    <br />
    <div>
        <h3>Skills In Demand <span className= "betabadge">BETA</span></h3>
    </div>
    <br />
      <div className="row">
          <div className="tabthis" style={{bottom:"0"}}>
              <div className="leftb" >
                <input type="text" id="mySearch" onChange={() => myFunction()} placeholder="Search skills..." title="Type in a skill" ></input>
              </div>
              <div className="rightb">
              <div className="skilldropdown">
              <button class="skilldropbtn">Topic: {cat}</button>
              <div className="skilldropdown-content">
              {S_Topics.map(S => {
          return <button onClick={openSearch} key={S}>{S}</button>
        })}
                </div>
              </div>
              </div>
          </div>
          <div className="left col" style={{backgroundColor:"lightgray", maxHeight:"350px", overflowY:"scroll", minWidth:"150px"}}>
                {showskilllist()}
          </div>

          <div className="right col chalkb">
            <div>
                <h4 id="Summary">{Summary} Summary</h4>
                <br/>
                {displaysummary()}
                <br/>
            </div>
          </div>
      </div>
       <>
            <div class="accordion row" id="Saccordion">
                <div class="card-skill">
                    <div class="card-header" id="headingOne">
                        <button class="btn btn-block text-center" type="button" data-toggle="collapse" data-target="#test" aria-expanded="false" aria-controls="collapseOne">
                           <h2>Don't see a skill? Try it here.</h2>
                        </button>
                    </div>

                    <div id="test" class="collapse" aria-labelledby="headingOne" data-parent="#Saccordion">
                          <div class="card-body row">
                                <form id="contact-form" onSubmit={handleChange} style={{width:'350px', margin:'auto'}}>
                                    <div>
                                        <label style={{color:'white', fontSize:'24px'}}>SKILL:</label>
                                        <input required id="topic" name="topic" type="text"  className="shadow-lg form-control" style={{maxWidth:'400px', padding: 'auto'}}/>
                                        <br/>
                                        <button type="submit" className="btn btn-primary" >Summarize</button>
                                        <button type="reset" onClick={() => setResponse("")}className="btn btn-danger" >Remove</button>
                                    </div>
                                </form>
                                {showtopicresponse()}
                          </div>
                    </div>
                </div>
            </div>
          </>
    </div>
  </>
  )

}

export default SkillsSection
