import React, { useState }from "react"
import "./styles.scss"
import PropTypes from 'prop-types';
import {setCookie, getCookie } from './AltLogin/Cookies.js'



export default function LoginPage() {
  const [password, setPassword] = useState('');
  const [email, setEmail] = useState('');
  const [message, setMessage] = useState('');
  const [emessage, setEMessage] = useState('');
  const [isLoading, setIsLoading] = useState();




 const submitLogin = async () => {
    setMessage('')
    setEMessage('')
    setIsLoading(true)
    const encodedemail = window.btoa(email)
    const encodedpass = window.btoa(password)
    console.log()

    const Data = () => {
        return {"email": encodedemail,"p_w": encodedpass}
    }
    //const url = `http://localhost:3000/private/auth/user/${encodedemail}`
    const url = `https://portfolio_be-1-k2619905.deta.app/private/auth/user/${encodedemail}`


    try {
    const Data_input = Data()

    const Data_Body = {"userLogin": Data_input}
    const response = await fetch(url,{
        method: "POST",
        headers: {
         accept: "application/json",
         "Content-Type": "application/json",
         "API-AKJ": "initial_upload_Alpha",
        },
        body: JSON.stringify(Data_Body),
    });

    if (!response.ok) {
        console.log(response.status)
        throw new Error("Sorry something went wrong when accessing private route")
    }

    const data = await response.json()

    if (data.message === 'Authenticated User'){
        setMessage(data.message)

        setCookie("user_email", data.email,data.cookie_time_min);
        setCookie("user_access", data.status_code,data.cookie_time_min);
        setCookie("access_token", data.session_id,data.cookie_time_min);
        window.location.assign(window.location  + "/Portfolio")
        } else {
        setEMessage(data.message)
        }

    /*const result = Object.entries(data)*/
    } catch(error){
    console.log(error.message);
    }
    setIsLoading()
  }


  return (
    <div className="parallax">
    <div className="Auth-form-container">
      <form id="regForm" className="Auth-form">
        <div className="Auth-form-content">
          <h3 className="Auth-form-title">Alternative Sign In  <span className= "betabadge">BETA</span></h3>

          <div className="form-group mt-3">
            <label>Email address</label>
            <input
              type="email"
              className="form-control mt-1"
              placeholder="Enter email"
              onChange={e => setEmail(e.target.value)}
              required
            />
          </div>
          <div className="form-group mt-3">
            <label>Password</label>
            <input
              type="password"
              className="form-control mt-1"
              placeholder="Enter password"
              onChange={e => setPassword(e.target.value)}
              required
            />
          </div>
            {isLoading? <p>Loading...</p>:""}
            {message ? <p style={{color:'green'}}>{message}</p> : <p style={{color:'red'}}>{emessage}</p>}
          <div className="d-grid gap-2 mt-3">
          <p className="btn-link mt-2 btn"style={{float:'left'}}>
            <a href="/Portfolio/signup" style={{cursor: "pointer"}}>Sign Up</a>
          </p>
            <a type="submit" className="btn btn-primary" style={{float:'right'}} onClick={(()=>submitLogin())}>
              Submit
            </a>
          </div>
          {/*<p className="forgot-password text-right mt-2">
            Forgot <a>password?</a>
          </p>*/}

        </div>
      </form>
    </div>
    </div>

  )
}
