import React, { useState } from "react";
import axios from "axios";
import Dictaphone from "./Dictaphone"
import SpeechRecognition, { useSpeechRecognition } from 'react-speech-recognition';
import microPhoneIcon from "./microphone.svg";
import { useAuth0 } from "@auth0/auth0-react";
import { getCookie } from '../../AltLogin/Cookies.js'




export default function ChatGPT(user_check) {
  const [prompt, setPrompt] = useState("");
  const [previousprompt, setPreviousPrompt] = useState("");
  const [response, setResponse] = useState("");
  /*const HTTP = "https://portfolio_be-1-k2619905.deta.app/chat";*/
  const HTTP = "http://127.0.0.1:8000/chat";
  const [isLoading, setIsLoading] = useState(false);
  const [hasError, setHasError] = useState(false);
  const [hasError1, setHasError1] = useState(false);
  const [Error, setError] = useState("")
  const [tscript, setTScript] = useState("");
  const [ourText, setOurText] = useState("")
  const msg = new SpeechSynthesisUtterance()
  const { user, isAuthenticated, getAccessTokenSilently } = useAuth0();


  const domain = process.env.REACT_APP_AUTH0_DOMAIN;
  const clientId = process.env.REACT_APP_AUTH0_CLIENT_ID;
  const authpurl = process.env.P_REACT_APP_AUTH0_TOKEN_URL
  const authcs = process.env.P_REACT_APP_AUTH0_CLIENT_S
  const paudience = process.env.P_REACT_APP_AUDIENCE
  const Grant_type = process.env.P_REACT_APP_GRANT_TYPE


  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setHasError();
    setHasError1();
    setError("");

    const C_check = getCookie("access_token")

    try {
        if (C_check !== "" || C_check !== undefined){
            axios.get(`${HTTP}?prompt_i=${prompt}`, {
          headers:{
             accept: "application/json",
              "API-COOKIE": C_check,
             }
          })
          .then((res) => {
            setResponse(res.data);
            setIsLoading(false);
            return
          })
          .catch((error) => {
            setError(error)
            setHasError(true);
            setIsLoading(false);

          });
        setPrompt(""); }
    } catch(error){
        return
        console.log(error.message);
    }

    console.log(Error)
    try {
        const token = await getAccessTokenSilently(authpurl, {
            method: "POST",
            header: {
             "content-type": "application/x-www-form-urlencoded"},
            "client_id":clientId,
            "client_secret":authcs,
            "audience":paudience,
            "grant_type":Grant_type,

        });
        axios
          .get(`${HTTP}?prompt_i=${prompt}`, {
          headers:{
             accept: "application/json",
             authorization: `Bearer ${token}`,
             }
          })
          .then((res) => {
            setResponse(res.data);
            setIsLoading(false);
          })
          .catch((error) => {
            setHasError1(true);
            setIsLoading(false);
          });
        setPrompt("");
        return
    } catch(error){

    setError("An Error has occurred: "+ error.message)
    console.log(error.message);
    }

  };

  const speechHandler = (msg) => {
    msg.text = response
    window.speechSynthesis.speak(msg)
    {if (window.speechSynthesis.speaking !== true)
    setResponse("")}
  }


  const handlePrompt = (e) => {
    setIsLoading(false);
    setHasError();
    setHasError1();
    setResponse("")
    setPrompt(e.target.value);

  };

  const SubmitTranscript = (e) => {
    setIsLoading(false)
    setHasError();
    setHasError1();
    setResponse("")
    setPrompt(transcript);

    }

    const {
    transcript,
    listening,
    resetTranscript,
    browserSupportsSpeechRecognition
  } = useSpeechRecognition();

  if (!browserSupportsSpeechRecognition) {
    return <span>Browser doesn't support speech recognition.</span>;
  }

  if (!window.speechSynthesis)
    return <span>Browser does not support Speech Synthesis</span>;

  return (
  <>
    <div className=" container-sm p-1 text-light">
      {" "}
      <h2 className="title text-center text-light">ChatGPT API Integration</h2>
      <p> This React component is an integrated chatbot component for this page that uses GPT-3 to generate natural
      language responses. It takes in user input and uses GPT-3 to generate a response. The component has a text input
      field for the user to type in their query, and a button to submit the query. When the user submits the query,
      the component sends the query to GPT-3 and receives a response. The response is then displayed in the
      component.
      </p>
      <p>Deep learning is a subset of machine learning that uses algorithms to model high-level abstractions in
      data. It is a type of artificial intelligence that uses multi-layered neural networks to learn from large
      amounts of data. Deep learning algorithms are able to learn from data without relying on task-specific rules
       and can be used for a variety of tasks, such as image recognition, natural language processing, and speech
       recognition.
       </p>
      <div>
      <img src={microPhoneIcon} width="25" className="microphone-icon"  alt=" "/>
          <p>Microphone Status: {listening ? 'ON' : 'OFF'}</p>
          <div className= "btn-group" role="group">
          <button type="button" className="btn btn-primary" onClick={SpeechRecognition.startListening}>Start</button>
          <button type="button" className="btn btn-primary" onClick={SpeechRecognition.stopListening}>Stop</button>
          <button type="button" className="btn btn-primary" onClick={resetTranscript}>Reset</button>
          <button type="button" className="btn btn-primary" onClick={SubmitTranscript}>Submit Transcript</button>
      </div>
      <div>
      <br />
      <p>Transcript: {transcript}</p>
      </div>
    </div>
      <form className="form text-light" onSubmit={handleSubmit}>
          <div className="form-group text-light">
            <label htmlFor="exampleInputEmail1" className="text-light blink_me">Ask Questions:</label>
            <input
            className="shadow-lg form-control text-dark"
            type="text"
            placeholder="Enter text"
            value= {prompt}
            onChange={handlePrompt}
            id="promptInput" aria-describedby="promptHelp" placeholder="Enter text" />
            <small id="promptHelp" className="form-text text-light text-muted">Disclaimer: The user is solely responsible for any inputs to the chatbot. The chatbot is not responsible for any consequences of the user's inputs. The chatbot is not responsible for any damages or losses resulting from the user's inputs. The chatbot is not responsible for any offensive, inappropriate, or illegal content that may be generated by the user's inputs.</small>
          </div>{" "}
        {/* <button className="btn btn-accept w-100" type="submit">
          Go
        </button> */}
      </form>
      { response ? <>
      <h4>Response Buttons:</h4>
        <div className= "btn-group" role="group">

          <button type="button" className="btn btn-primary" onClick={() => speechHandler(msg)}>Play</button>
          <button type="button" className="btn btn-primary" onClick={() => window.speechSynthesis.pause(msg)}>Pause</button>
          <button type="button" className="btn btn-primary" onClick={() => window.speechSynthesis.resume(msg)}>Resume</button>
          <button type="button" className="btn btn-primary" onClick={() => window.speechSynthesis.cancel(msg)}>Stop</button>
        </div>
        </>:<div></div>}
      <br />
      <br />
      <div style={{border: '3px solid rgba(3, 138, 255, 0.9)', borderRadius: '10px', transparency: '0.5', backgroundColor: 'rgba(192,192,192,0.5)'}}>
        <p className="text-light" style={{padding: '10px'}}>
{/*         {(hasError ===true) ?"Sorry, something went wrong ": ""} */}
        {isLoading ? "Loading..." : <>  {response ? response : "Ask me anything..."}</>}
        </p>
      </div>
    </div>
    </>
  );
}