import { Auth0Provider } from "@auth0/auth0-react";
import React from "react";
import { useNavigate } from "react-router-dom";

export const Auth0ProviderWithNavigate = ({ children }) => {
  const navigate = useNavigate();

  const domain = process.env.REACT_APP_AUTH0_DOMAIN;
  const clientId = process.env.REACT_APP_AUTH0_CLIENT_ID;
  const redirectUri = process.env.REACT_APP_REDIRECT_URI;
  const Audience = process.env.REACT_APP_AUDIENCE;
  const Scope = process.env.REACT_APP_SCOPE;
  const CacheLocation = process.env.REACT_APP_CACHELOCATION;


  const onRedirectCallback = (appState) => {
    navigate(appState?.previousPath || window.location.pathname);
  };

  if (!(domain && clientId && redirectUri)) {
    return null;
  }

    // console.log(`${window.location.origin}/Portfolio`)
  return (
    <Auth0Provider
      domain={domain}
      clientId={clientId}
      authorizationParams={{
      redirect_uri: `${window.location.origin}/Portfolio`,
      audience: Audience,
      scope: Scope,
      useRefresherTokens: true,
      cacheLocation: CacheLocation
      }}
      onRedirectCallback={onRedirectCallback}
    >
      {children}
    </Auth0Provider>
  );
};