import { useAuth0 } from "@auth0/auth0-react";
import React from "react";
import { getCookie, deleteCookie } from './AltLogin/Cookies.js'


function LogoutButton(props) {


      const { logout } = useAuth0();
      const user_c = getCookie('access_token')
      const CName = props.ClassName
      const SName = props.style


      const AltLogout = async() => {
        try {
            const C_u_id = getCookie("ajs_user_id")
            let CE_u_id = C_u_id.replace("|","%7C")
            const url = `https://portfolio_be-1-k2619905.deta.app/private/session/user/delete/${CE_u_id}`
            const C_check = getCookie("access_token")
            const response = await fetch(url, {
                method:'DELETE',
                headers: {
                 accept: "application/json",
                  "API-COOKIE": C_check,
                },
            });

            if (!response.ok) {
                console.log(response.status)
                throw new Error("Sorry something went wrong when accessing private route. Response is : " + JSON.stringify(response))
            }
            const data = await response.json()
            console.log(data)
            deleteCookie('access_token')
            deleteCookie('user_access')
            deleteCookie('ajs_user_id')
            deleteCookie('user_email')
            window.location.reload();

            return

        } catch(error){ console.log(error)}
      }

if (user_c !== ""){return <a  className={CName} style={SName} onClick={() => AltLogout()}>
      Alternative Log Out
    </a>}
else {
  return <a  className={CName} style={SName} onClick={() => logout({ logoutParams: { returnTo: `${window.location.origin}/Portfolio/` } })}>
      Log Out
    </a>
  }
};

export default LogoutButton;