import React, { useEffect, useState, useMemo } from "react"
import Pagination from './Pagination'
import JPost from './JPost'


let PageSize = 5;

const JPData = () => {
  const [currentPage, setCurrentPage] = useState(0);
  const [JPData, setJPData] = useState([])
  const [error, setError] = useState("")
  const url = 'http://127.0.0.1:8000/jobs';

  useEffect(() => {
    fetchData()
  }, [])


  const fetchData = async () => {
    setError("")
    try {
      const response = await fetch(url)
      if (!response.ok) {
        // If the API responds meaningful error message,
        // then you can get it by calling response.statusText
        throw new Error("Sorry something went wrong")
      }
      const data = await response.json()
      setJPData(Object.values(data))
      setCurrentPage(currentPage+1)

      console.log(data)
    } catch (error) {
      // It is always recommended to define the error messages
      // in the client side rather than simply relying on the server messages,
      // since server messages might not make sense to end user most of the time.
      setError(error.message)
    }
  }


  const currentTableData = useMemo(() => {
  const firstPageIndex = (currentPage - 1) * PageSize;
  const lastPageIndex = firstPageIndex + PageSize;
  console.log(currentPage)
  return JPData.slice(firstPageIndex, lastPageIndex);
  }, [currentPage]);






  return (
  <>
    <div class="jcontainer px-4 py-5" style = {{"width":"70%"}}>
      {error && <p>{error}</p>}
      {currentTableData.length > 0 && (


        <div class="my-5 column" style ={{ width: "100%"}}>
        <JPost />
          {currentTableData.map((item,index) => (
          <>

            <div class="accordion overflow-auto" id="accordionExample">
                <div class="card-job">
                    <div class="card-header" id="headingOne">
                          <h5 class="mb-0">
                            <button class="btn btn-link btn-block text-left" type="button" data-toggle="collapse" data-target={`#${item.name}`} aria-expanded="false" aria-controls="collapseOne">
                                {item.Job_name}
                               <p> Start Date: {item.Start_Date}<br/>
                                    Location: {item.Job_Location} </p>
                            </button>
                          </h5>
                    </div>

                    <div id={item.name} class="collapse" aria-labelledby="headingOne" data-parent="#accordionExample">
                          <div class="card-body px-4 overflowAuto">
                            {item.Job_Description} <br/> <br/>
                            <button type = "submit">Submit Resume </button>
                          </div>
                    </div>
                </div>
            </div>
          </>
          )) }
        </div>
      )}
      <Pagination
        className="pagination-bar"
        totalCount={JPData.length}
        currentPage={currentPage}
        pageSize={PageSize}
        onPageChange={page => setCurrentPage(page)}
      />

    </div>
</>
  )
}

export default JPData
